def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    opp_infos = []
    prev_bids = []
    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is None:
            pbid = 0.0
        prev_bids.append(float(pbid))
        opp_infos.append({
            'id': agent_id,
            'bid': float(pbid),
            'hp': opp.get('hp', 10),
            'budget': opp.get('budget', 0.0),
            'nwd': opp.get('no_water_days', 0),
            'req': opp.get('water_requirement', WATER_REQ)
        })

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = sorted(prev_bids, reverse=True)[int(1)] if len(prev_bids) >= 2 else highest_prev
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    cindy_bid = None
    bob_bid = None
    eric_bid = None
    for info in opp_infos:
        lid = info['id'].lower()
        if lid == 'cindy':
            cindy_bid = info['bid']
        elif lid == 'bob':
            bob_bid = info['bid']
        elif lid == 'eric':
            eric_bid = info['bid']

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    scarce = supply <= 17
    ample = supply >= 22

    strong_count = 0
    for info in opp_infos:
        if info['budget'] >= 120 and info['hp'] > 2:
            strong_count += 1

    if urgency >= 5:
        target = max(110.0, second_prev + 3.0)
        if eric_bid is not None:
            target = max(target, eric_bid + 4.0)
        if bob_bid is not None and bob_bid < 120:
            target = max(target, bob_bid + 2.0)
        if cindy_bid is not None and cindy_bid <= budget and hp <= 2:
            target = max(target, cindy_bid + 1.0)
        return float(min(budget, target))

    if scarce:
        if urgency >= 3:
            target = max(92.0, avg_prev + 6.0)
            if eric_bid is not None:
                target = max(target, eric_bid + 3.0)
            return float(min(budget, target))
        if strong_count >= 2:
            return float(min(budget, 16.0))
        return float(min(budget, 28.0))

    if ample:
        if urgency >= 2:
            target = max(58.0, (eric_bid + 2.0) if eric_bid is not None else 58.0)
            return float(min(budget, target))
        return float(min(budget, 24.0))

    if urgency >= 3:
        target = 84.0
        if eric_bid is not None:
            target = max(target, eric_bid + 2.5)
        return float(min(budget, target))

    if highest_prev >= 125.0:
        return float(min(budget, 26.0))

    target = 52.0
    if eric_bid is not None:
        target = max(target, eric_bid + 1.5)
    elif bob_bid is not None and bob_bid < 90:
        target = max(target, bob_bid + 1.5)

    if day >= 8 and hp >= 6 and budget > 140:
        target += 6.0

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for agent_id, st in opponents_status.items():
        if st.get('alive'):
            alive_opps.append((agent_id, st))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids to infer who pressures prices
    yesterday_bids = []
    for agent_id, st in alive_opps:
        prev = st.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Identify Cindy-like heavy bidder by yesterday bid magnitude
    heavy_prev = None
    for agent_id, st in alive_opps:
        prev = st.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                b = float(prev.get('bid'))
            except Exception:
                continue
            if heavy_prev is None or b > heavy_prev[1]:
                heavy_prev = (agent_id, b)

    heavy_bid = heavy_prev[1] if heavy_prev is not None else 0.0

    # Base strategy: bid higher when supply is tight or HP is low.
    # Supply factor: lower supply -> higher urgency.
    supply_tightness = (float(MAX_SUPPLY) - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_tightness < 0.0:
        supply_tightness = 0.0
    if supply_tightness > 1.0:
        supply_tightness = 1.0

    urgency_hp = 0.0
    if hp <= 2.0:
        urgency_hp = 1.0
    elif hp <= 4.0:
        urgency_hp = 0.6
    elif hp <= 6.0:
        urgency_hp = 0.3
    else:
        urgency_hp = 0.1

    urgency_no_water = 0.0
    if no_water_days >= 2:
        urgency_no_water = 0.8
    elif no_water_days == 1:
        urgency_no_water = 0.4
    else:
        urgency_no_water = 0.1

    urgency = 0.45 * supply_tightness + 0.35 * urgency_hp + 0.20 * urgency_no_water

    # If a clear heavy bidder existed yesterday (Cindy), avoid matching her exactly.
    # Instead, bid enough to not be completely priced out.
    # Target: either slightly below heavy_bid scale, or a fraction of DAILY_SALARY.
    if heavy_bid >= 110.0:
        target = 0.62 * heavy_bid
    elif highest_prev_bid >= 80.0:
        target = 0.55 * highest_prev_bid
    else:
        target = DAILY_SALARY * 0.55

    # Adjust by urgency and remaining budget.
    # Cap to avoid overspending: never exceed ~1.1*DAILY_SALARY per day when possible.
    target = target * (0.75 + 0.5 * urgency)
    hard_cap = DAILY_SALARY * 1.1

    bid = min(budget, hard_cap, target)

    # If very low budget, still bid something to extend survival when urgent.
    if bid < 1.0 and urgency >= 0.7:
        bid = min(budget, DAILY_SALARY * 0.3)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 # From meta-round state

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid minimally to secure water
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.05)

    # Analyze yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Determine bid based on my HP and opponent behavior

    # Critical HP: Must win to survive
    if my_status['hp'] <= 3:
        # Bid very aggressively. Try to outbid anyone.
        bid_multiplier = 0.95
        if EPISODE_DAYS - day_context['day'] <= 2: # Last 2 days
            bid_multiplier = 1.0 # Bid full salary if desperate

        # If opponents were bidding high, ensure we exceed their max.
        if highest_prev_bid > DAILY_SALARY * 0.8: # If high competition yesterday
            return min(my_status['budget'], max(DAILY_SALARY * bid_multiplier, highest_prev_bid + 5.0))
        else:
            return min(my_status['budget'], DAILY_SALARY * bid_multiplier)

    # Healthy HP: Try to win, but be mindful of budget
    else: # my_status['hp'] > 3
        # If highest previous bid was very high, we might need to match/exceed
        if highest_prev_bid >= DAILY_SALARY * 0.8: # Opponents are aggressive
            # Bid slightly above yesterday's highest to secure water, but not overspend
            return min(my_status['budget'], max(DAILY_SALARY * 0.7, highest_prev_bid + 2.0))
        elif highest_prev_bid >= DAILY_SALARY * 0.5: # Moderate competition
            # Bid slightly above yesterday's highest
            return min(my_status['budget'], max(DAILY_SALARY * 0.6, highest_prev_bid + 1.0))
        else: # Low competition or no significant bids yesterday
            # Bid a moderate amount, enough to win against low bidders, but save budget
            return min(my_status['budget'], max(DAILY_SALARY * 0.55, highest_prev_bid + 1.0))

